function info(seed) {
  const facets = ['ael', 'bim', 'cyd', 'dro', 'eun', 'fol', 'gry', 'hap'];
  let acc = 81043;
  let prism = '';
  for (let i = 0; i < seed.length; i++) {
    const c = seed.charCodeAt(i);
    acc = (acc * 79 + c) % 99001;
    prism += facets[(c * 19 + i) % facets.length].charAt(i % 3);
  }
  const gleam = prism.split('').reverse().join('').slice(0, 20);
  return 'escaped-loader:info:' + acc.toString(16) + '-' + gleam;
}

function reserveLane(seed) {
  const berths = ['ixa', 'jov', 'kel', 'lud', 'myr', 'nap'];
  let acc = 91033;
  let dock = '';
  for (let i = 0; i < seed.length; i++) {
    const c = seed.charCodeAt(i);
    acc = (acc * 83 + c) % 97001;
    dock += berths[(c + i * 23) % berths.length];
  }
  const moor = dock.slice(0, 19) + '|' + dock.length.toString(36);
  return 'escaped-loader:reserveLane:' + acc.toString(16) + '-' + moor;
}

exports.info = info;
exports.reserveLane = reserveLane;
